import boto3
import os

def get_document_by_id(table_name: str, document_id: str) -> dict | None:
    """
    Fetches a document by its identifier from an Amazon DynamoDB table.

    Args:
        table_name: The name of the DynamoDB table.
        document_id: The ID of the document to fetch.

    Returns:
        The fetched document as a dictionary, or None if not found.
    """
    # Initialize a DynamoDB client
    # AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY, and AWS_REGION are typically
    # picked up from environment variables or AWS credential files.
    dynamodb = boto3.client('dynamodb', region_name=os.environ.get('AWS_REGION', 'us-east-1'))

    try:
        response = dynamodb.get_item(
            TableName=table_name,
            Key={
                'id': {'S': document_id}  # Assuming 'id' is the primary key and is a string type
            }
        )

        item = response.get('Item')
        if item:
            # DynamoDB returns items with type descriptors (e.g., {'S': 'value', 'N': '123'})
            # This helper function can deserialize them into standard Python types.
            def deserialize_dynamodb_item(item_dict):
                deserialized_item = {}
                for key, value in item_dict.items():
                    if 'S' in value:
                        deserialized_item[key] = value['S']
                    elif 'N' in value:
                        deserialized_item[key] = int(value['N']) # Or float(value['N'])
                    elif 'BOOL' in value:
                        deserialized_item[key] = value['BOOL']
                    elif 'M' in value:
                        deserialized_item[key] = deserialize_dynamodb_item(value['M'])
                    elif 'L' in value:
                        deserialized_item[key] = [deserialize_dynamodb_item({'_': v})['_'] for v in value['L']]
                    # Add more type handling as needed (B, SS, NS, BS, NULL, etc.)
                return deserialized_item

            return deserialize_dynamodb_item(item)
        else:
            return None
    except Exception as e:
        print(f"Error fetching document from DynamoDB: {e}")
        return None
